// ============================================
// File: pages/Interview.jsx
// Purpose: Voice Interview Frontend - UI only
// ============================================
//
// Frontend is responsible for:
// 1) Capturing microphone (getUserMedia)
// 2) Sending audio chunks to WebSocket
// 3) Receiving audio chunks and playing them (MediaSource)
// 4) Start/Stop buttons for control
//
// Not allowed:
// - Any API keys
// - Any direct connection to OpenAI or ElevenLabs
// - Any AI logic
// - Any complex audio processing (only PCM conversion for streaming)
//
// All AI logic is in Backend

import React, { useState, useEffect, useRef } from 'react';
import { useSearchParams } from 'react-router-dom';
import '../design-styles.css';

const API_BASE = import.meta.env.VITE_API_URL || 'http://localhost:5000';
const WS_BASE = API_BASE.replace(/^http/, 'ws');
const VOICE_WS_PATH = '/ws/voice-interview';

const CAPTURE_SAMPLE_RATE = 16000;

function float32ToPcmBase64(float32Array) {
  const pcm = new Int16Array(float32Array.length);
  for (let i = 0; i < float32Array.length; i++) {
    const s = Math.max(-1, Math.min(1, float32Array[i]));
    pcm[i] = s < 0 ? s * 0x8000 : s * 0x7fff;
  }
  let binary = '';
  for (let i = 0; i < pcm.length; i++) {
    binary += String.fromCharCode(pcm[i] & 0xff, (pcm[i] >> 8) & 0xff);
  }
  return btoa(binary);
}

function base64ToArrayBuffer(base64) {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes.buffer;
}

/** MediaSource streaming player - supports MP3 chunks without decodeAudioData.
 *  onPlaybackEnded: called when audio playback actually ends (end-of-speech detection). */
function createMediaSourcePlayer(onError, onPlaybackEnded) {
  if (!window.MediaSource) {
    onError?.('MediaSource API not supported');
    return null;
  }
  const mediaSource = new MediaSource();
  const audio = document.createElement('audio');
  audio.autoplay = true;
  document.body.appendChild(audio);
  const url = URL.createObjectURL(mediaSource);
  audio.src = url;

  audio.addEventListener('ended', () => {
    onPlaybackEnded?.();
    audio.remove();
    URL.revokeObjectURL(url);
  });

  const chunkQueue = [];
  let isAppending = false;
  let sourceBuffer = null;
  let noMoreChunks = false;
  let hasStartedPlay = false;

  function tryEndStream() {
    if (noMoreChunks && chunkQueue.length === 0 && sourceBuffer && !sourceBuffer.updating) {
      try { mediaSource.endOfStream(); } catch (_) {}
    }
  }

  function appendNext() {
    if (isAppending || !sourceBuffer) return;
    if (chunkQueue.length === 0) {
      tryEndStream();
      return;
    }
    const chunk = chunkQueue.shift();
    if (!chunk || chunk.byteLength === 0) { appendNext(); return; }
    try {
      isAppending = true;
      sourceBuffer.appendBuffer(chunk);
    } catch (e) {
      onError?.(e?.message || 'appendBuffer failed');
      isAppending = false;
      appendNext();
    }
  }

  mediaSource.addEventListener('sourceopen', () => {
    if (sourceBuffer) return;
    try {
      if (MediaSource.isTypeSupported('audio/mpeg')) {
        sourceBuffer = mediaSource.addSourceBuffer('audio/mpeg');
      } else if (MediaSource.isTypeSupported('audio/mp4')) {
        sourceBuffer = mediaSource.addSourceBuffer('audio/mp4');
      } else {
        onError?.('MP3/MP4 not supported in MediaSource');
        return;
      }
      sourceBuffer.mode = 'sequence';
      sourceBuffer.addEventListener('updateend', () => {
        isAppending = false;
        if (!hasStartedPlay) {
          hasStartedPlay = true;
          audio.play().catch(() => {});
        }
        appendNext();
      });
      appendNext();
    } catch (e) {
      onError?.(e?.message || 'addSourceBuffer failed');
    }
  });

  mediaSource.addEventListener('sourceended', () => {
    // Don't remove audio here — sourceended = transmission ended, playback may still be ongoing.
    // Removal only in audio.ended (when playback actually ends).
  });

  return {
    appendChunk(buf) {
      if (noMoreChunks) return;
      chunkQueue.push(buf);
      appendNext();
    },
    endStream() {
      noMoreChunks = true;
      tryEndStream();
      appendNext();
    },
    destroy() {
      try {
        mediaSource.endOfStream();
      } catch (_) {}
      audio.remove();
      URL.revokeObjectURL(url);
    }
  };
}

/* Same design as the main container in Design page (questions container) */
const questionContainerStyle = {
  position: 'relative',
  minHeight: '200px',
  padding: '30px',
  background: 'linear-gradient(180deg, rgba(15, 23, 42, 0.98) 0%, rgba(2, 6, 23, 0.98) 100%)',
  backdropFilter: 'blur(20px)',
  WebkitBackdropFilter: 'blur(20px)',
  borderRadius: '12px',
  border: '2px solid rgba(34, 211, 238, 0.3)',
  boxShadow: '0 8px 24px rgba(0, 0, 0, 0.6), 0 0 0 1px rgba(34, 211, 238, 0.1), inset 0 1px 0 rgba(255, 255, 255, 0.03)',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  overflow: 'hidden',
};

const Interview = () => {
  const [searchParams] = useSearchParams();
  const candidateId = searchParams.get('candidateId');

  const [candidate, setCandidate] = useState(null);
  const [loadingCandidate, setLoadingCandidate] = useState(!!candidateId);
  const [candidateError, setCandidateError] = useState(null);

  const wsRef = useRef(null);
  const [connectionStatus, setConnectionStatus] = useState('idle');
  const [serverState, setServerState] = useState(null);
  const [sessionId, setSessionId] = useState(null);
  const [lastError, setLastError] = useState(null);
  const [micActive, setMicActive] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [lastTranscript, setLastTranscript] = useState('');
  const [streamingTranscript, setStreamingTranscript] = useState(''); // Real-time partial from Web Speech API
  const [lastAgentReply, setLastAgentReply] = useState('');
  const [apiKeysReady, setApiKeysReady] = useState(null);

  const speechRecognitionRef = useRef(null);
  const accumulatedTranscriptRef = useRef('');
  const serverStateRef = useRef(serverState);
  serverStateRef.current = serverState;

  const mediaStreamRef = useRef(null);
  const captureContextRef = useRef(null);
  const audioSeqRef = useRef(0);
  const mediaSourcePlayerRef = useRef(null);
  const audioChunkBufferRef = useRef([]);
  const lastChunkTimeRef = useRef(0);
  const playbackEndedSentRef = useRef(false);
  const playbackEndedFallbackRef = useRef(null);

  useEffect(() => {
    if (!candidateId) {
      setLoadingCandidate(false);
      return;
    }
    let cancelled = false;
    setLoadingCandidate(true);
    setCandidateError(null);
    fetch(`${API_BASE}/api/candidates/${candidateId}`)
      .then((res) => {
        if (!res.ok) throw new Error('Candidate not found');
        return res.json();
      })
      .then((result) => {
        if (!cancelled && result?.data) setCandidate(result.data);
      })
      .catch((err) => {
        if (!cancelled) setCandidateError(err.message);
      })
      .finally(() => {
        if (!cancelled) setLoadingCandidate(false);
      });
    return () => { cancelled = true; };
  }, [candidateId]);

  useEffect(() => {
    return () => {
      if (wsRef.current) {
        wsRef.current.close();
        wsRef.current = null;
      }
    };
  }, []);

  // Manual mic management - opens only when isListening === true
  useEffect(() => {
    if (!isListening) {
      // Close mic when stopping
      if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach((t) => t.stop());
        mediaStreamRef.current = null;
      }
      if (captureContextRef.current) {
        captureContextRef.current.close().catch(() => {});
        captureContextRef.current = null;
      }
      setMicActive(false);
      return;
    }

    // Open mic when isListening === true
    let cancelled = false;
    navigator.mediaDevices
      .getUserMedia({ audio: { channelCount: 1, sampleRate: CAPTURE_SAMPLE_RATE } })
      .then((stream) => {
        if (cancelled) {
          stream.getTracks().forEach((t) => t.stop());
          return;
        }
        mediaStreamRef.current = stream;
        const ctx = new (window.AudioContext || window.webkitAudioContext)({ sampleRate: CAPTURE_SAMPLE_RATE });
        captureContextRef.current = ctx;
        const src = ctx.createMediaStreamSource(stream);
        const bufferSize = 4096;
        const processor = ctx.createScriptProcessor(bufferSize, 1, 1);
        processor.onaudioprocess = (e) => {
          const ws = wsRef.current;
          if (ws?.readyState !== WebSocket.OPEN) return;
          // Send audio only when serverState === 'LISTENING'
          if (serverState !== 'LISTENING') return;
          const input = e.inputBuffer.getChannelData(0);
          const base64 = float32ToPcmBase64(input);
          audioSeqRef.current += 1;
          ws.send(JSON.stringify({ type: 'audio_chunk', seq: audioSeqRef.current, pcmBase64: base64 }));
        };
        src.connect(processor);
        processor.connect(ctx.destination);
        setMicActive(true);
      })
      .catch((err) => {
        if (!cancelled) setLastError(err?.message || 'Microphone access denied');
      });

    return () => {
      cancelled = true;
      if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach((t) => t.stop());
        mediaStreamRef.current = null;
      }
      if (captureContextRef.current) {
        captureContextRef.current.close().catch(() => {});
        captureContextRef.current = null;
      }
      setMicActive(false);
    };
  }, [isListening, serverState]);

  // Web Speech API: real-time streaming transcript (captures words as user speaks)
  useEffect(() => {
    const SpeechRecognitionAPI = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SpeechRecognitionAPI || serverState !== 'LISTENING') {
      if (speechRecognitionRef.current) {
        try { speechRecognitionRef.current.stop(); } catch (_) {}
        speechRecognitionRef.current = null;
      }
      if (serverState !== 'LISTENING') {
        setStreamingTranscript('');
      }
      return;
    }

    const lang = new URLSearchParams(window.location.search).get('language') || 'ar';
    const recognition = new SpeechRecognitionAPI();
    recognition.continuous = true;
    recognition.interimResults = true;
    recognition.lang = lang === 'en' || lang === 'english' ? 'en-US' : 'ar-SA';

    recognition.onresult = (event) => {
      let interim = '';
      let finalText = '';
      for (let i = event.resultIndex; i < event.results.length; i++) {
        const transcript = event.results[i][0].transcript;
        if (event.results[i].isFinal) {
          finalText += transcript;
        } else {
          interim += transcript;
        }
      }
      if (finalText) {
        accumulatedTranscriptRef.current = (accumulatedTranscriptRef.current + ' ' + finalText).trim();
        setLastTranscript(accumulatedTranscriptRef.current);
        setStreamingTranscript('');
      }
      if (interim) {
        setStreamingTranscript(interim);
      }
    };

    recognition.onend = () => {
      if (serverStateRef.current === 'LISTENING' && speechRecognitionRef.current === recognition) {
        try { recognition.start(); } catch (_) {}
      }
    };

    recognition.onerror = (e) => {
      if (e.error !== 'no-speech' && e.error !== 'aborted') {
        console.warn('[SpeechRecognition]', e.error);
      }
    };

    try {
      recognition.start();
      speechRecognitionRef.current = recognition;
    } catch (e) {
      console.warn('[SpeechRecognition] start failed:', e);
    }

    return () => {
      speechRecognitionRef.current = null;
      try { recognition.stop(); } catch (_) {}
    };
  }, [serverState]);

  const connectVoiceInterview = () => {
    if (wsRef.current?.readyState === WebSocket.OPEN) return;
    setConnectionStatus('connecting');
    setLastError(null);
    const params = new URLSearchParams();
    if (candidateId) params.set('candidateId', candidateId);
    const lang = new URLSearchParams(window.location.search).get('language') || 'ar';
    params.set('language', lang);
    const url = `${WS_BASE}${VOICE_WS_PATH}${params.toString() ? `?${params}` : ''}`;
    const ws = new WebSocket(url);
    wsRef.current = ws;

    ws.onopen = () => {
      setConnectionStatus('connected');
      setIsListening(true);
      ws.send(JSON.stringify({ type: 'start_listening' }));
    };

    ws.onmessage = (event) => {
      try {
        const msg = JSON.parse(event.data);
        if (msg.type === 'ready' && msg.sessionId) {
          setSessionId(msg.sessionId);
          // Don't start listening automatically - user starts manually
        }
        if (msg.type === 'config') setApiKeysReady({ hasOpenAI: msg.hasOpenAI, hasElevenLabs: msg.hasElevenLabs });
        if (msg.type === 'state' && msg.state) {
          setServerState(msg.state);
          if (msg.state === 'LISTENING') {
            accumulatedTranscriptRef.current = '';
            setStreamingTranscript('');
            setLastTranscript('');
            mediaSourcePlayerRef.current = null;
            audioChunkBufferRef.current = [];
            lastChunkTimeRef.current = 0;
            playbackEndedSentRef.current = true;
            if (playbackEndedFallbackRef.current) {
              clearTimeout(playbackEndedFallbackRef.current);
              playbackEndedFallbackRef.current = null;
            }
          }
        }
        if (msg.type === 'tts_complete') {
          playbackEndedSentRef.current = false;
          if (playbackEndedFallbackRef.current) {
            clearTimeout(playbackEndedFallbackRef.current);
            playbackEndedFallbackRef.current = null;
          }
          const sendPlaybackEnded = () => {
            if (playbackEndedSentRef.current) return;
            playbackEndedSentRef.current = true;
            if (playbackEndedFallbackRef.current) {
              clearTimeout(playbackEndedFallbackRef.current);
              playbackEndedFallbackRef.current = null;
            }
            if (wsRef.current?.readyState === WebSocket.OPEN) {
              wsRef.current.send(JSON.stringify({ type: 'playback_ended' }));
            }
          };
          playbackEndedFallbackRef.current = setTimeout(sendPlaybackEnded, 12000);
          if (mediaSourcePlayerRef.current) {
            const SILENCE_MS = 250;
            const check = () => {
              if (Date.now() - lastChunkTimeRef.current >= SILENCE_MS) {
                if (mediaSourcePlayerRef.current) mediaSourcePlayerRef.current.endStream();
                return;
              }
              setTimeout(check, 50);
            };
            setTimeout(check, 50);
          } else if (audioChunkBufferRef.current.length > 0) {
            const chunks = audioChunkBufferRef.current;
            audioChunkBufferRef.current = [];
            const blob = new Blob(chunks, { type: 'audio/mpeg' });
            const url = URL.createObjectURL(blob);
            const fallbackAudio = new Audio(url);
            fallbackAudio.onended = () => {
              URL.revokeObjectURL(url);
              sendPlaybackEnded();
            };
            fallbackAudio.play().catch(() => {});
          }
        }
        if (msg.type === 'error') setLastError(msg.message || 'Error');
        if (msg.type === 'transcript' && msg.text) {
          setLastTranscript(msg.text);
          if (msg.isFinal) accumulatedTranscriptRef.current = msg.text;
        }
        if (msg.type === 'agent_reply' && msg.text) setLastAgentReply(msg.text);
        if (msg.type === 'audio_chunk' && msg.chunkBase64) {
          lastChunkTimeRef.current = Date.now();
          const buf = new Uint8Array(base64ToArrayBuffer(msg.chunkBase64));
          if (!mediaSourcePlayerRef.current) {
            const player = createMediaSourcePlayer(
              (err) => {
                setLastError(err || 'Audio playback error');
                mediaSourcePlayerRef.current = null;
              },
              () => {
                if (playbackEndedSentRef.current) return;
                playbackEndedSentRef.current = true;
                if (playbackEndedFallbackRef.current) {
                  clearTimeout(playbackEndedFallbackRef.current);
                  playbackEndedFallbackRef.current = null;
                }
                if (wsRef.current?.readyState === WebSocket.OPEN) {
                  wsRef.current.send(JSON.stringify({ type: 'playback_ended' }));
                }
              }
            );
            mediaSourcePlayerRef.current = player;
            if (player && audioChunkBufferRef.current.length > 0) {
              audioChunkBufferRef.current.forEach((b) => player.appendChunk(b));
              audioChunkBufferRef.current = [];
            }
          }
          if (mediaSourcePlayerRef.current) {
            mediaSourcePlayerRef.current.appendChunk(buf);
          } else {
            audioChunkBufferRef.current.push(buf);
          }
        }
      } catch {
        setLastError('Invalid message');
      }
    };

    ws.onclose = () => {
      wsRef.current = null;
      setConnectionStatus('closed');
      setServerState(null);
      setSessionId(null);
      setApiKeysReady(null);
    };

    ws.onerror = () => {
      setConnectionStatus('error');
      setLastError('WebSocket error');
    };
  };

  const disconnectVoiceInterview = () => {
    // Stop listening first
    setIsListening(false);
    if (wsRef.current?.readyState === WebSocket.OPEN) {
      wsRef.current.send(JSON.stringify({ type: 'stop_listening' }));
    }
    if (wsRef.current) {
      wsRef.current.close();
      wsRef.current = null;
    }
    if (mediaSourcePlayerRef.current) {
      mediaSourcePlayerRef.current.destroy();
      mediaSourcePlayerRef.current = null;
    }
    audioChunkBufferRef.current = [];
    setConnectionStatus('idle');
    setServerState(null);
    setSessionId(null);
    setLastError(null);
    setMicActive(false);
    setIsListening(false);
    setLastTranscript('');
    setStreamingTranscript('');
    setLastAgentReply('');
    accumulatedTranscriptRef.current = '';
  };

  const displayName = candidate
    ? `${candidate.firstName || ''} ${candidate.lastName || ''}`.trim() || candidate.email?.split('@')[0] || 'Candidate'
    : 'Candidate';
  const displayPosition = candidate?.positionAppliedFor || 'Position';

  return (
    <div dir="ltr"
      style={{
      minHeight: '100vh',
      padding: '40px 20px',
        background: 'linear-gradient(160deg, #0f172a 0%, #1e293b 35%, #0f172a 100%)',
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
        justifyContent: 'center',
      }}
    >
      <div
        style={{
          position: 'relative',
        width: '100%',
          maxWidth: '900px',
          background: 'linear-gradient(180deg, rgba(15, 23, 42, 0.98) 0%, rgba(2, 6, 23, 0.98) 100%)',
          backdropFilter: 'blur(20px)',
          WebkitBackdropFilter: 'blur(20px)',
          borderRadius: '12px',
          padding: '32px 40px',
          border: '2px solid rgba(34, 211, 238, 0.3)',
          boxShadow: '0 8px 24px rgba(0, 0, 0, 0.6), 0 0 0 1px rgba(34, 211, 238, 0.1), inset 0 1px 0 rgba(255, 255, 255, 0.03)',
          overflow: 'hidden',
        }}
      >
        {/* Shimmer bar at top of container - like Design page */}
        <div
          style={{
            position: 'absolute',
            top: 0,
            left: 0,
            right: 0,
            height: '2px',
            background: 'linear-gradient(90deg, transparent, rgba(34, 211, 238, 0.5), rgba(34, 211, 238, 0.8), rgba(34, 211, 238, 0.5), transparent)',
            animation: 'shimmer 3s ease-in-out infinite',
          }}
        />
        {/* Header: Voice Interview */}
        <div style={{ textAlign: 'center', marginBottom: '28px' }}>
          <h1
            style={{
              fontSize: '30px',
              fontWeight: 700,
              margin: 0,
              background: 'linear-gradient(135deg, #60A5FA, #3B82F6)',
              WebkitBackgroundClip: 'text',
              WebkitTextFillColor: 'transparent',
              backgroundClip: 'text',
            }}
          >
            Voice Interview
          </h1>
          <p style={{ margin: '12px 0 0', fontSize: '0.9rem', color: '#F1F5F9' }}>
            {loadingCandidate ? 'Loading...' : candidateError ? 'Candidate not available' : `${displayName} - ${displayPosition}`}
          </p>
        </div>

        {/* AI Assistant card */}
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'flex-start',
            gap: '16px',
            background: 'linear-gradient(180deg, #1e293b 0%, #172033 100%)',
            borderRadius: '14px',
            padding: '16px 20px',
            marginBottom: '24px',
            border: '1px solid rgba(56, 189, 248, 0.2)',
            boxShadow: '0 0 20px rgba(56, 189, 248, 0.06)',
          }}
        >
          <div style={{ flex: 1, height: '1px', borderBottom: '2px dotted rgba(56, 189, 248, 0.35)', marginLeft: '8px' }} />
          <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
            <span style={{ color: '#F8FAFC', fontSize: '0.95rem', textAlign: 'left' }}>
              <div>AI Assistant</div>
              <div style={{ fontSize: '0.8rem', color: '#E2E8F0' }}>evaalo</div>
            </span>
            <div
              style={{
                width: '44px',
                height: '44px',
                borderRadius: '50%',
                background: 'linear-gradient(135deg, #8b5cf6 0%, #a78bfa 100%)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                fontSize: '1.4rem',
              }}
            >
              🤖
            </div>
          </div>
        </div>

        {/* Two panels: User transcript | Agent reply */}
        <div
          style={{
            display: 'grid',
            gridTemplateColumns: '1fr 1fr',
            gap: '20px',
            marginBottom: '24px',
          }}
        >
          <div style={questionContainerStyle}>
            <div
              style={{
                position: 'absolute',
                top: 0,
                left: 0,
                right: 0,
                height: '2px',
                background: 'linear-gradient(90deg, transparent, rgba(34, 211, 238, 0.5), rgba(34, 211, 238, 0.8), rgba(34, 211, 238, 0.5), transparent)',
                animation: 'shimmer 3s ease-in-out infinite',
              }}
            />
            <div style={{ textAlign: 'left', width: '100%', padding: '0 8px' }}>
              <span style={{ color: 'rgba(203, 213, 225, 0.9)', fontSize: '1rem', display: 'block' }}>
                {(lastTranscript || streamingTranscript) ? `«${[lastTranscript, streamingTranscript].filter(Boolean).join(' ')}»` : ''}
              </span>
            </div>
          </div>
          <div style={questionContainerStyle}>
            <div
              style={{
                position: 'absolute',
                top: 0,
                left: 0,
                right: 0,
                height: '2px',
                background: 'linear-gradient(90deg, transparent, rgba(34, 211, 238, 0.5), rgba(34, 211, 238, 0.8), rgba(34, 211, 238, 0.5), transparent)',
                animation: 'shimmer 3s ease-in-out infinite',
              }}
            />
            <div style={{ textAlign: 'left', width: '100%', padding: '0 8px' }}>
              <span style={{ color: 'rgba(203, 213, 225, 0.9)', fontSize: '1rem', display: 'block' }}>
                {lastAgentReply ? lastAgentReply : (serverState === 'SPEAKING' ? 'Responding...' : '')}
              </span>
            </div>
          </div>
        </div>

        {/* User card — same design as AI Assistant card */}
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'flex-start',
            gap: '16px',
            background: 'linear-gradient(180deg, #1e293b 0%, #172033 100%)',
            borderRadius: '14px',
            padding: '16px 20px',
            border: '1px solid rgba(56, 189, 248, 0.2)',
            boxShadow: '0 0 20px rgba(56, 189, 248, 0.06)',
          }}
        >
          <div
            style={{
              width: '44px',
              height: '44px',
              borderRadius: '50%',
              background: 'linear-gradient(135deg, #0ea5e9 0%, #38bdf8 100%)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              fontSize: '1.4rem',
            }}
          >
            👤
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
            <span style={{ color: '#F8FAFC', fontSize: '0.95rem', textAlign: 'left' }}>
              <div>User</div>
              <div style={{ fontSize: '0.8rem', color: '#E2E8F0' }}>
                {loadingCandidate ? 'Loading...' : candidateError ? '—' : displayName}
              </div>
            </span>
          </div>
          <div style={{ flex: 1, height: '1px', borderBottom: '2px dotted rgba(56, 189, 248, 0.35)', marginRight: '8px' }} />
        </div>

        {/* API keys warning */}
        {connectionStatus === 'connected' && apiKeysReady && (!apiKeysReady.hasOpenAI || !apiKeysReady.hasElevenLabs) && (
          <div
            style={{
              marginBottom: '20px',
              padding: '16px 20px',
              background: 'rgba(239, 68, 68, 0.1)',
              borderRadius: '10px',
              border: '1px solid rgba(239, 68, 68, 0.4)',
            }}
          >
            <p style={{ margin: 0, fontSize: '0.95rem', color: 'rgba(248, 113, 113, 0.95)', fontWeight: 600 }}>
              API keys not found on server
            </p>
            <p style={{ margin: '8px 0 0', fontSize: '0.85rem', color: 'rgba(203, 213, 225, 0.9)' }}>
              Please add OPENAI_API_KEY and ELEVENLABS_API_KEY to the .env file in apps/backend
            </p>
          </div>
        )}

        {lastError && (
          <p style={{ textAlign: 'center', marginBottom: '12px', fontSize: '0.85rem', color: 'rgba(248, 113, 113, 0.95)' }}>{lastError}</p>
        )}

        {/* Start / End button */}
        <div style={{ textAlign: 'center', marginTop: '28px', display: 'flex', flexWrap: 'wrap', gap: '12px', justifyContent: 'center' }}>
          {connectionStatus !== 'connected' ? (
            <button
              type="button"
              className="workflow-btn-primary"
              onClick={connectVoiceInterview}
              disabled={!candidateId || connectionStatus === 'connecting'}
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: '10px',
                padding: '14px 28px',
                fontSize: '1.05rem',
                fontWeight: '600',
                cursor: candidateId && connectionStatus !== 'connecting' ? 'pointer' : 'not-allowed',
                opacity: candidateId && connectionStatus !== 'connecting' ? 1 : 0.6,
              }}
            >
              <span style={{ fontSize: '1.25rem' }}>▶</span>
              <span>{connectionStatus === 'connecting' ? 'Starting...' : 'Start'}</span>
            </button>
          ) : (
            <button
              type="button"
              onClick={disconnectVoiceInterview}
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: '10px',
                padding: '14px 28px',
                fontSize: '1.05rem',
            fontWeight: '600',
                color: '#fff',
                background: 'linear-gradient(135deg, #ef4444 0%, #dc2626 100%)',
                border: 'none',
                borderRadius: '12px',
                boxShadow: '0 4px 20px rgba(239, 68, 68, 0.35)',
                cursor: 'pointer',
                transition: 'transform 0.2s ease, box-shadow 0.2s ease',
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.transform = 'translateY(-2px)';
                e.currentTarget.style.boxShadow = '0 6px 24px rgba(239, 68, 68, 0.45)';
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.transform = 'translateY(0)';
                e.currentTarget.style.boxShadow = '0 4px 20px rgba(239, 68, 68, 0.35)';
              }}
            >
              <span style={{ fontSize: '1.25rem' }}>⏹</span>
              <span>End</span>
            </button>
          )}
          {!candidateId && (
            <p style={{ width: '100%', marginTop: '10px', fontSize: '0.85rem', color: 'rgba(148, 163, 184, 0.9)' }}>
              Add candidateId to the URL to start the interview
            </p>
          )}
        </div>
      </div>
    </div>
  );
};

export default Interview;
