import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import Navigation from '../components/Navigation';

const WrittenInterview = () => {
    const navigate = useNavigate();
    const [candidates, setCandidates] = useState([]);
    const [loading, setLoading] = useState(true);
    const [filter, setFilter] = useState('all'); // all, hire, consider, reject
    const [expandedRows, setExpandedRows] = useState(new Set());
    const [showFilterMenu, setShowFilterMenu] = useState(false);
    const [filters, setFilters] = useState({
        position: '',
        dateFrom: '',
        dateTo: ''
    });

    useEffect(() => {
        fetchCandidates();
    }, []);

    // Close filter menu when clicking outside
    useEffect(() => {
        const handleClickOutside = (event) => {
            if (showFilterMenu && !event.target.closest('.filter-menu-container')) {
                setShowFilterMenu(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [showFilterMenu]);

    const fetchCandidates = async () => {
        try {
            setLoading(true);
            const response = await fetch('http://localhost:5000/api/candidates');
            const result = await response.json();
            
            console.log('📥 Fetched candidates:', result);
            
            if (result.success && result.data) {
                // تصفية المرشحين الذين لديهم writtenInterviewEvaluation
                const candidatesWithEvaluation = result.data.filter(
                    candidate => {
                        const hasEvaluation = candidate.writtenInterviewEvaluation;
                        if (hasEvaluation) {
                            console.log('✅ Candidate with evaluation:', candidate.firstName, candidate.lastName, candidate.writtenInterviewEvaluation);
                        }
                        return hasEvaluation;
                    }
                );
                
                console.log('📊 Candidates with Written Interview Evaluation:', candidatesWithEvaluation.length);
                console.log('📋 All candidates:', result.data.length);
                
                setCandidates(candidatesWithEvaluation);
            } else {
                console.warn('⚠️ No candidates data received');
            }
        } catch (error) {
            console.error('❌ Error fetching candidates:', error);
        } finally {
            setLoading(false);
        }
    };

    const getRecommendationColor = (recommendation) => {
        switch (recommendation) {
            case 'Hire':
                return { bg: 'rgba(16, 185, 129, 0.2)', border: 'rgba(16, 185, 129, 0.4)', text: '#10B981' };
            case 'Consider':
                return { bg: 'rgba(245, 158, 11, 0.2)', border: 'rgba(245, 158, 11, 0.4)', text: '#F59E0B' };
            case 'Reject':
                return { bg: 'rgba(239, 68, 68, 0.2)', border: 'rgba(239, 68, 68, 0.4)', text: '#EF4444' };
            default:
                return { bg: 'rgba(148, 163, 184, 0.2)', border: 'rgba(148, 163, 184, 0.4)', text: '#94A3B8' };
        }
    };

    const getScoreColor = (score) => {
        if (score >= 80) return { bg: 'rgba(16, 185, 129, 0.2)', text: '#10B981' };
        if (score >= 60) return { bg: 'rgba(245, 158, 11, 0.2)', text: '#F59E0B' };
        return { bg: 'rgba(239, 68, 68, 0.2)', text: '#EF4444' };
    };

    const handleShare = async (candidate) => {
        const candidateId = candidate._id || candidate.id;
        const baseUrl = window.location.origin;
        const interviewLink = `${baseUrl}/interview?candidateId=${encodeURIComponent(candidateId)}`;

        const candidateData = {
            name: `${candidate.firstName || ''} ${candidate.lastName || ''}`.trim() || candidate.email?.split('@')[0] || 'Unknown',
            position: candidate.positionAppliedFor || 'N/A',
            score: candidate.writtenInterviewEvaluation?.overall_score || 0,
            recommendation: candidate.writtenInterviewEvaluation?.recommendation || 'N/A',
            summary: candidate.writtenInterviewEvaluation?.summary || 'No summary available',
            email: candidate.email || 'N/A',
            phone: candidate.phone || 'N/A'
        };

        const shareText = `🎤 رابط المقابلة الصوتية مع الإيجنت\n\n` +
            `👤 المرشح: ${candidateData.name}\n` +
            `💼 الوظيفة: ${candidateData.position}\n\n` +
            `🔗 رابط مقابلة فويس انترفيو (صوتية مع الإيجنت - بدون أفاتار):\n${interviewLink}\n\n` +
            `---\n` +
            `📋 تقرير التقييم الكتابي\n` +
            `⭐ الدرجة: ${candidateData.score}%\n` +
            `🎯 التوصية: ${candidateData.recommendation}\n` +
            `📧 البريد: ${candidateData.email}\n` +
            `📱 الهاتف: ${candidateData.phone}\n\n` +
            `📝 الملخص:\n${candidateData.summary}`;

        // Try Web Share API first (mobile/desktop) — إرسال رابط المقابلة الصوتية
        if (navigator.share) {
            try {
                await navigator.share({
                    title: `رابط المقابلة الصوتية - ${candidateData.name}`,
                    text: `رابط المقابلة الصوتية مع الإيجنت للمرشح ${candidateData.name} (${candidateData.position}):\n${interviewLink}`,
                    url: interviewLink
                });
                return;
            } catch (err) {
                if (err.name !== 'AbortError') {
                    console.error('Error sharing:', err);
                }
            }
        }

        // Fallback: Copy to clipboard
        try {
            await navigator.clipboard.writeText(shareText);
            alert('✅ تم نسخ رابط فويس انترفيو ومعلومات المرشح إلى الحافظة!');
        } catch (err) {
            console.error('Failed to copy:', err);
            prompt('رابط المقابلة الصوتية ومعلومات المرشح (انسخ النص):', shareText);
        }
    };

    const filteredCandidates = candidates.filter(c => {
        // Filter by recommendation
        if (filter !== 'all' && c.writtenInterviewEvaluation?.recommendation !== filter) {
            return false;
        }
        
        // Filter by position
        if (filters.position && c.positionAppliedFor?.toLowerCase().includes(filters.position.toLowerCase()) === false) {
            return false;
        }
        
        // Filter by date range
        if (c.createdAt) {
            const candidateDate = new Date(c.createdAt);
            
            if (filters.dateFrom) {
                const fromDate = new Date(filters.dateFrom);
                fromDate.setHours(0, 0, 0, 0);
                if (candidateDate < fromDate) {
                    return false;
                }
            }
            
            if (filters.dateTo) {
                const toDate = new Date(filters.dateTo);
                toDate.setHours(23, 59, 59, 999);
                if (candidateDate > toDate) {
                    return false;
                }
            }
        }
        
        return true;
    });

    return (
        <>
            <style>{`
                @keyframes slideDown {
                    from {
                        opacity: 0;
                        max-height: 0;
                        transform: translateY(-10px);
                    }
                    to {
                        opacity: 1;
                        max-height: 1000px;
                        transform: translateY(0);
                    }
                }
            `}</style>
        <div style={{ minHeight: '100vh', background: 'linear-gradient(135deg, #0F172A 0%, #1E293B 100%)' }}>
            <Navigation />
            
            <div style={{
                padding: '70px 20px 40px',
                maxWidth: '1400px',
                margin: '0 auto',
                background: 'transparent'
            }}>
                {/* Header */}
                <div style={{
                    marginBottom: '40px',
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    flexWrap: 'wrap',
                    gap: '20px'
                }}>
                    <div className="header-actions" style={{ display: 'flex', alignItems: 'center', gap: '20px' }}>
                        <button
                            className="btn btn-secondary"
                            onClick={() => navigate(-1)}
                        >
                            <svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                                <path d="M12.5 15L7.5 10L12.5 5" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                            </svg>
                            <span className="btn-text">Back</span>
                        </button>
                        <h1 style={{
                            fontSize: '30px',
                            fontWeight: 700,
                            background: 'linear-gradient(135deg, #60A5FA, #3B82F6)',
                            WebkitBackgroundClip: 'text',
                            WebkitTextFillColor: 'transparent',
                            backgroundClip: 'text',
                            marginBottom: '0',
                            marginTop: '0',
                            margin: '0',
                            padding: '12px 20px',
                            border: '1px solid rgba(34, 211, 238, 0.3)',
                            borderRadius: '10px',
                            background: 'linear-gradient(135deg, rgba(96, 165, 250, 0.1), rgba(59, 130, 246, 0.1))',
                            backdropFilter: 'blur(10px)',
                            display: 'inline-block'
                        }}>
                            <span style={{
                                background: 'linear-gradient(135deg, #60A5FA, #3B82F6)',
                                WebkitBackgroundClip: 'text',
                                WebkitTextFillColor: 'transparent',
                                backgroundClip: 'text'
                        }}>
                            Written Interview Evaluations
                            </span>
                        </h1>
                    </div>

                    {/* Actions */}
                    <div style={{ 
                        display: 'flex', 
                        gap: '10px', 
                        flexWrap: 'wrap', 
                        alignItems: 'center',
                        justifyContent: 'flex-end'
                    }}>
                        <div className="header-actions" style={{ display: 'flex', gap: '12px', alignItems: 'center' }}>
                        <button
                                className="btn btn-secondary"
                            onClick={fetchCandidates}
                            >
                                <svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                                    <path d="M10 3.33333C6.31807 3.33333 3.33333 6.31807 3.33333 10C3.33333 13.6819 6.31807 16.6667 10 16.6667C13.6819 16.6667 16.6667 13.6819 16.6667 10" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
                                    <path d="M6.66667 3.33333L10 6.66667L13.3333 3.33333" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" fill="none"/>
                                    <path d="M10 1.66667V6.66667" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round"/>
                                </svg>
                                <span className="btn-text">Refresh</span>
                        </button>
                        
                        {/* Filter Button */}
                        <div className="filter-menu-container" style={{ position: 'relative' }}>
                            <button 
                                className="btn btn-secondary"
                                onClick={() => setShowFilterMenu(!showFilterMenu)}
                                style={{ 
                                    cursor: 'pointer',
                                    display: 'flex',
                                    alignItems: 'center',
                                    gap: '8px'
                                }}
                            >
                                <svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                                    <path d="M2.5 5H17.5M5 10H15M7.5 15H12.5" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
                                </svg>
                                <span className="btn-text">Filter</span>
                                {(filters.position || filters.dateFrom || filters.dateTo) && (
                                    <span style={{ 
                                        width: '6px', 
                                        height: '6px', 
                                        borderRadius: '50%', 
                                        background: '#22d3ee',
                                        marginLeft: '-4px'
                                    }}></span>
                                )}
                            </button>
                            {showFilterMenu && (
                                <div className="color-dropdown-menu open" style={{
                                    position: 'absolute',
                                    top: '100%',
                                    right: 0,
                                    marginTop: '8px',
                                    minWidth: '280px',
                                    zIndex: 1000,
                                    padding: '20px'
                                }}>
                                    <div style={{ marginBottom: '16px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                        <h3 style={{ color: '#fff', fontSize: '16px', fontWeight: 600, margin: 0 }}>Filter Evaluations</h3>
                                        <button
                                            onClick={() => {
                                                setFilters({ position: '', dateFrom: '', dateTo: '' });
                                                setShowFilterMenu(false);
                                            }}
                                            className="btn-small"
                                            style={{
                                                background: 'transparent',
                                                border: 'none',
                                                color: '#94A3B8',
                                                cursor: 'pointer',
                                                fontSize: '12px',
                                                padding: '4px 8px'
                                            }}
                                        >
                                            Clear All
                                        </button>
                                    </div>
                                    <div className="form-group" style={{ marginBottom: '16px' }}>
                                        <label className="form-label" style={{ display: 'block', color: '#CBD5E1', fontSize: '13px', marginBottom: '8px', fontWeight: 500 }}>
                                            Position
                                        </label>
                                        <input
                                            type="text"
                                            placeholder="Search position..."
                                            value={filters.position}
                                            onChange={(e) => setFilters({ ...filters, position: e.target.value })}
                                            className="form-input"
                                            style={{
                                                width: '100%',
                                                padding: '8px 12px',
                                                background: 'rgba(15, 23, 42, 0.8)',
                                                border: '1px solid rgba(34, 211, 238, 0.3)',
                                                borderRadius: '8px',
                                                color: '#fff',
                                                fontSize: '13px'
                                            }}
                                        />
                                    </div>
                                    <div className="form-group" style={{ marginBottom: '16px' }}>
                                        <label className="form-label" style={{ display: 'block', color: '#CBD5E1', fontSize: '13px', marginBottom: '8px', fontWeight: 500 }}>
                                            Date From
                                        </label>
                                        <input
                                            type="date"
                                            value={filters.dateFrom}
                                            onChange={(e) => setFilters({ ...filters, dateFrom: e.target.value })}
                                            className="form-input"
                                            style={{
                                                width: '100%',
                                                padding: '8px 12px',
                                                background: 'rgba(15, 23, 42, 0.8)',
                                                border: '1px solid rgba(34, 211, 238, 0.3)',
                                                borderRadius: '8px',
                                                color: '#fff',
                                                fontSize: '13px'
                                            }}
                                        />
                                    </div>
                                    <div className="form-group" style={{ marginBottom: '16px' }}>
                                        <label className="form-label" style={{ display: 'block', color: '#CBD5E1', fontSize: '13px', marginBottom: '8px', fontWeight: 500 }}>
                                            Date To
                                        </label>
                                        <input
                                            type="date"
                                            value={filters.dateTo}
                                            onChange={(e) => setFilters({ ...filters, dateTo: e.target.value })}
                                            className="form-input"
                                            style={{
                                                width: '100%',
                                                padding: '8px 12px',
                                                background: 'rgba(15, 23, 42, 0.8)',
                                                border: '1px solid rgba(34, 211, 238, 0.3)',
                                                borderRadius: '8px',
                                                color: '#fff',
                                                fontSize: '13px'
                                            }}
                                        />
                                    </div>
                                </div>
                            )}
                        </div>
                        
                        {/* Filter Buttons */}
                        {['all', 'Hire', 'Consider', 'Reject'].map((filterOption) => {
                            const isActive = filter === filterOption.toLowerCase();
                            
                            return (
                                <button
                                    key={filterOption}
                                        className="btn btn-secondary"
                                    onClick={() => setFilter(filterOption.toLowerCase())}
                                    style={{
                                            background: isActive ? 'rgba(34, 211, 238, 0.2)' : 'rgba(15, 23, 42, 0.8)',
                                            borderColor: isActive ? 'rgba(34, 211, 238, 0.6)' : 'rgba(34, 211, 238, 0.3)',
                                            color: isActive ? '#22d3ee' : 'rgba(255, 255, 255, 0.95)'
                                        }}
                                    >
                                        {filterOption === 'all' && (
                                            <svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                                                <path d="M2.5 5H17.5M5 10H15M7.5 15H12.5" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
                                            </svg>
                                        )}
                                        {filterOption === 'Hire' && (
                                            <svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                                                <path d="M10 2.5L12.5 7.5L17.5 8.75L14.5 12.5L15.5 17.5L10 15L4.5 17.5L5.5 12.5L2.5 8.75L7.5 7.5L10 2.5Z" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                                            </svg>
                                        )}
                                        {filterOption === 'Consider' && (
                                            <svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                                                <circle cx="10" cy="10" r="7.5" stroke="currentColor" strokeWidth="2"/>
                                                <path d="M10 6V10L13 13" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
                                            </svg>
                                        )}
                                        {filterOption === 'Reject' && (
                                            <svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                                                <circle cx="10" cy="10" r="7.5" stroke="currentColor" strokeWidth="2"/>
                                                <path d="M7.5 7.5L12.5 12.5M12.5 7.5L7.5 12.5" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
                                            </svg>
                                        )}
                                        <span className="btn-text">{filterOption === 'all' ? 'All' : filterOption}</span>
                                </button>
                            );
                        })}
                        </div>
                    </div>
                </div>

                {/* Table */}
                {loading ? (
                    <div style={{ textAlign: 'center', padding: '60px', color: '#94A3B8' }}>
                        Loading...
                    </div>
                ) : filteredCandidates.length === 0 ? (
                    <div style={{ 
                        textAlign: 'center', 
                        padding: '60px', 
                        color: '#94A3B8',
                        background: 'rgba(15, 23, 42, 0.5)',
                        borderRadius: '12px',
                        border: '1px solid rgba(148, 163, 184, 0.1)'
                    }}>
                        <div style={{ marginBottom: '20px', fontSize: '48px' }}>📋</div>
                        <div style={{ fontSize: '18px', marginBottom: '10px', color: '#CBD5E1' }}>
                            {filter === 'all' 
                                ? 'لا توجد تقييمات مقابلات كتابية'
                                : `لا يوجد مرشحون بتوصية "${filter}"`
                            }
                        </div>
                        <div style={{ fontSize: '14px', color: '#94A3B8', marginTop: '10px', marginBottom: '20px' }}>
                            {filter === 'all' 
                                ? 'تأكد من إرسال البيانات من n8n مع حقل writtenInterviewEvaluation'
                                : 'جرب تغيير الفلتر أو تحديث الصفحة'
                            }
                        </div>
                        <button
                            onClick={fetchCandidates}
                            style={{
                                padding: '10px 20px',
                                borderRadius: '8px',
                                border: '1px solid rgba(96, 165, 250, 0.4)',
                                background: 'rgba(96, 165, 250, 0.2)',
                                color: '#60A5FA',
                                cursor: 'pointer',
                                fontSize: '14px',
                                fontWeight: 600
                            }}
                        >
                            🔄 تحديث البيانات
                        </button>
                    </div>
                ) : (
                    <div style={{
                        background: 'rgba(15, 23, 42, 0.5)',
                        borderRadius: '12px',
                        border: '1px solid rgba(34, 211, 238, 0.2)',
                        overflow: 'hidden',
                        boxShadow: '0 4px 12px rgba(0, 0, 0, 0.3)'
                    }}>
                        <div style={{ overflowX: 'auto' }}>
                            <table style={{ 
                                width: '100%', 
                                borderCollapse: 'separate',
                                borderSpacing: 0,
                                border: '1px solid rgba(34, 211, 238, 0.2)',
                                borderRadius: '8px',
                                overflow: 'hidden'
                            }}>
                                <thead>
                                    <tr style={{ 
                                        background: 'linear-gradient(180deg, rgba(30, 41, 59, 0.95) 0%, rgba(15, 23, 42, 0.95) 100%)',
                                        borderBottom: '2px solid rgba(34, 211, 238, 0.5)'
                                    }}>
                                        <th style={{ 
                                            padding: '16px', 
                                            textAlign: 'left', 
                                            color: '#22d3ee', 
                                            fontWeight: 600, 
                                            fontSize: '14px', 
                                            width: '40px',
                                            borderRight: '1px solid rgba(34, 211, 238, 0.3)'
                                        }}></th>
                                        <th style={{ 
                                            padding: '16px', 
                                            textAlign: 'left', 
                                            color: '#22d3ee', 
                                            fontWeight: 600, 
                                            fontSize: '14px',
                                            minWidth: '250px',
                                            borderRight: '1px solid rgba(34, 211, 238, 0.3)'
                                        }}>Candidate</th>
                                        <th style={{ 
                                            padding: '16px', 
                                            textAlign: 'center', 
                                            color: '#22d3ee', 
                                            fontWeight: 600, 
                                            fontSize: '14px',
                                            borderRight: '1px solid rgba(34, 211, 238, 0.3)'
                                        }}>Overall Score</th>
                                        <th style={{ 
                                            padding: '16px', 
                                            textAlign: 'left', 
                                            color: '#22d3ee', 
                                            fontWeight: 600, 
                                            fontSize: '14px',
                                            borderRight: '1px solid rgba(34, 211, 238, 0.3)'
                                        }}>Fit for Role</th>
                                        <th style={{ 
                                            padding: '16px', 
                                            textAlign: 'center', 
                                            color: '#22d3ee', 
                                            fontWeight: 600, 
                                            fontSize: '14px',
                                            borderRight: '1px solid rgba(34, 211, 238, 0.3)'
                                        }}>Recommendation</th>
                                        <th style={{ 
                                            padding: '16px', 
                                            textAlign: 'center', 
                                            color: '#22d3ee', 
                                            fontWeight: 600, 
                                            fontSize: '14px', 
                                            width: '80px'
                                        }}>Share</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {filteredCandidates.map((candidate, index) => {
                                        const evaluation = candidate.writtenInterviewEvaluation;
                                        const scoreColors = getScoreColor(evaluation?.overall_score || 0);
                                        const recColors = getRecommendationColor(evaluation?.recommendation);
                                        const candidateId = candidate._id || candidate.id;
                                        const isExpanded = expandedRows.has(candidateId);
                                        
                                        const toggleRow = (e) => {
                                            // Don't expand if clicking on share button
                                            if (e.target.tagName === 'BUTTON' || e.target.closest('button')) {
                                                return;
                                            }
                                            setExpandedRows(prev => {
                                                const newSet = new Set(prev);
                                                if (newSet.has(candidateId)) {
                                                    newSet.delete(candidateId);
                                                } else {
                                                    newSet.add(candidateId);
                                                }
                                                return newSet;
                                            });
                                        };
                                        
                                        return (
                                            <React.Fragment key={candidateId}>
                                            <tr 
                                                style={{
                                                    borderTop: '1px solid rgba(34, 211, 238, 0.3)',
                                                    borderBottom: index < filteredCandidates.length - 1 ? '1px solid rgba(34, 211, 238, 0.3)' : '1px solid rgba(34, 211, 238, 0.3)',
                                                    transition: 'all 0.2s ease',
                                                    cursor: 'pointer',
                                                    background: 'transparent'
                                                }}
                                                onClick={toggleRow}
                                                onMouseEnter={(e) => {
                                                    e.currentTarget.style.background = 'rgba(34, 211, 238, 0.05)';
                                                    e.currentTarget.style.borderTop = '1px solid rgba(34, 211, 238, 0.5)';
                                                    e.currentTarget.style.borderBottom = '1px solid rgba(34, 211, 238, 0.5)';
                                                }}
                                                onMouseLeave={(e) => {
                                                    e.currentTarget.style.background = 'transparent';
                                                    e.currentTarget.style.borderTop = '1px solid rgba(34, 211, 238, 0.3)';
                                                    e.currentTarget.style.borderBottom = index < filteredCandidates.length - 1 ? '1px solid rgba(34, 211, 238, 0.3)' : '1px solid rgba(34, 211, 238, 0.3)';
                                                }}
                                            >
                                                {/* Expand/Collapse Icon */}
                                                <td style={{ 
                                                    padding: '16px', 
                                                    textAlign: 'center', 
                                                    width: '40px',
                                                    borderRight: '1px solid rgba(34, 211, 238, 0.3)',
                                                    borderLeft: '1px solid rgba(34, 211, 238, 0.1)'
                                                }}>
                                                    <svg 
                                                        width="20" 
                                                        height="20" 
                                                        viewBox="0 0 20 20" 
                                                        fill="none" 
                                                        xmlns="http://www.w3.org/2000/svg"
                                                        style={{
                                                            transform: isExpanded ? 'rotate(90deg)' : 'rotate(0deg)',
                                                            transition: 'transform 0.3s ease',
                                                            color: '#22d3ee'
                                                        }}
                                                    >
                                                        <path d="M7.5 5L12.5 10L7.5 15" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                                                    </svg>
                                                </td>
                                                {/* Candidate Name */}
                                                <td style={{ 
                                                    padding: '16px', 
                                                    minWidth: '250px',
                                                    borderRight: '1px solid rgba(34, 211, 238, 0.3)',
                                                    borderLeft: '1px solid rgba(34, 211, 238, 0.1)'
                                                }}>
                                                    <div style={{ display: 'flex', alignItems: 'flex-start', gap: '12px' }}>
                                                        {/* Profile Photo */}
                                                        <div style={{
                                                            width: '48px',
                                                            height: '48px',
                                                            borderRadius: '50%',
                                                            overflow: 'hidden',
                                                            flexShrink: 0,
                                                            border: '2px solid rgba(34, 211, 238, 0.3)',
                                                            background: 'linear-gradient(135deg, #06B6D4, #3B82F6)',
                                                            display: 'flex',
                                                            alignItems: 'center',
                                                            justifyContent: 'center',
                                                            boxShadow: '0 2px 8px rgba(6, 182, 212, 0.2)'
                                                        }}>
                                                            {candidate.photo || candidate.profilePhoto ? (
                                                                <img 
                                                                    src={candidate.photo || candidate.profilePhoto} 
                                                                    alt={`${candidate.firstName || ''} ${candidate.lastName || ''}`.trim() || 'Profile'} 
                                                                    style={{ 
                                                                        width: '100%', 
                                                                        height: '100%', 
                                                                        objectFit: 'cover' 
                                                                    }}
                                                                    onError={(e) => {
                                                                        e.target.style.display = 'none';
                                                                        e.target.nextSibling.style.display = 'flex';
                                                                    }}
                                                                />
                                                            ) : null}
                                                            <div style={{ 
                                                                display: candidate.photo || candidate.profilePhoto ? 'none' : 'flex',
                                                                alignItems: 'center', 
                                                                justifyContent: 'center',
                                                                width: '100%',
                                                                height: '100%',
                                                                fontSize: '20px',
                                                                fontWeight: 600,
                                                                color: '#fff'
                                                            }}>
                                                                {(candidate.firstName?.[0] || candidate.lastName?.[0] || candidate.email?.[0] || '?').toUpperCase()}
                                                            </div>
                                                        </div>
                                                        <div style={{ flex: 1, minWidth: 0 }}>
                                                            <div style={{ 
                                                                color: '#F1F5F9', 
                                                                fontWeight: 600, 
                                                                marginBottom: '4px',
                                                                whiteSpace: 'normal',
                                                                wordWrap: 'break-word',
                                                                lineHeight: '1.4',
                                                                fontSize: '14px'
                                                            }}>
                                                            {candidate.firstName && candidate.lastName
                                                                ? `${candidate.firstName} ${candidate.lastName}`
                                                                : candidate.email?.split('@')[0] || 'Unknown'
                                                            }
                                                        </div>
                                                        <div style={{ 
                                                            color: '#94A3B8', 
                                                            fontSize: '12px',
                                                            whiteSpace: 'normal',
                                                            wordWrap: 'break-word',
                                                            lineHeight: '1.4',
                                                            marginBottom: '4px'
                                                        }}>
                                                            {candidate.positionAppliedFor || 'N/A'}
                                                        </div>
                                                        {candidate.createdAt && (
                                                            <div style={{ 
                                                                color: '#64748B', 
                                                                fontSize: '11px',
                                                                whiteSpace: 'normal',
                                                                wordWrap: 'break-word',
                                                                lineHeight: '1.3',
                                                                marginTop: '4px',
                                                                display: 'flex',
                                                                alignItems: 'center',
                                                                gap: '4px'
                                                            }}>
                                                                <svg width="12" height="12" viewBox="0 0 12 12" fill="none" xmlns="http://www.w3.org/2000/svg" style={{ opacity: 0.7 }}>
                                                                    <circle cx="6" cy="6" r="5" stroke="currentColor" strokeWidth="1"/>
                                                                    <path d="M6 3V6L8 8" stroke="currentColor" strokeWidth="1" strokeLinecap="round"/>
                                                                </svg>
                                                                {new Date(candidate.createdAt).toLocaleString('en-US', {
                                                                    year: 'numeric',
                                                                    month: 'short',
                                                                    day: 'numeric',
                                                                    hour: '2-digit',
                                                                    minute: '2-digit'
                                                                })}
                                                            </div>
                                                        )}
                                                        </div>
                                                    </div>
                                                </td>

                                                {/* Overall Score */}
                                                <td style={{ 
                                                    padding: '16px', 
                                                    textAlign: 'center',
                                                    borderRight: '1px solid rgba(34, 211, 238, 0.3)',
                                                    borderLeft: '1px solid rgba(34, 211, 238, 0.1)'
                                                }}>
                                                    <div style={{
                                                        display: 'inline-block',
                                                        padding: '8px 16px',
                                                        borderRadius: '8px',
                                                        background: scoreColors.bg,
                                                        color: scoreColors.text,
                                                        fontWeight: 700,
                                                        fontSize: '18px'
                                                    }}>
                                                        {evaluation?.overall_score || 0}%
                                                    </div>
                                                </td>

                                                {/* Fit for Role */}
                                                <td style={{ 
                                                    padding: '16px', 
                                                    color: '#CBD5E1', 
                                                    fontSize: '14px',
                                                    borderRight: '1px solid rgba(34, 211, 238, 0.3)',
                                                    borderLeft: '1px solid rgba(34, 211, 238, 0.1)'
                                                }}>
                                                    {evaluation?.fit_for_role || 'N/A'}
                                                </td>

                                                {/* Recommendation */}
                                                <td style={{ 
                                                    padding: '16px', 
                                                    textAlign: 'center',
                                                    borderRight: '1px solid rgba(34, 211, 238, 0.3)',
                                                    borderLeft: '1px solid rgba(34, 211, 238, 0.1)'
                                                }}>
                                                    <div style={{
                                                        display: 'inline-block',
                                                        padding: '6px 12px',
                                                        borderRadius: '6px',
                                                        background: recColors.bg,
                                                        border: `1px solid ${recColors.border}`,
                                                        color: recColors.text,
                                                        fontWeight: 600,
                                                        fontSize: '13px'
                                                    }}>
                                                        {evaluation?.recommendation || 'N/A'}
                                                    </div>
                                                </td>

                                                {/* Share Button */}
                                                <td style={{ 
                                                    padding: '16px', 
                                                    textAlign: 'center',
                                                    borderLeft: '1px solid rgba(34, 211, 238, 0.1)'
                                                }}>
                                                    <button
                                                        onClick={() => handleShare(candidate)}
                                                        title="مشاركة رابط المقابلة الصوتية مع الإيجنت وتقييم المرشح"
                                                        style={{
                                                            width: '48px',
                                                            height: '48px',
                                                            borderRadius: '50%',
                                                            border: 'none',
                                                            background: 'linear-gradient(135deg, #10B981 0%, #059669 100%)',
                                                            backdropFilter: 'blur(10px)',
                                                            color: '#fff',
                                                            cursor: 'pointer',
                                                            display: 'flex',
                                                            alignItems: 'center',
                                                            justifyContent: 'center',
                                                            fontSize: '20px',
                                                            transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
                                                            boxShadow: '0 4px 12px rgba(16, 185, 129, 0.3), 0 0 0 1px rgba(34, 211, 238, 0.4)',
                                                            position: 'relative',
                                                            overflow: 'hidden'
                                                        }}
                                                        onMouseEnter={(e) => {
                                                            e.currentTarget.style.transform = 'scale(1.1) rotate(360deg)';
                                                            e.currentTarget.style.background = 'linear-gradient(135deg, #059669 0%, #047857 100%)';
                                                            e.currentTarget.style.boxShadow = '0 8px 24px rgba(16, 185, 129, 0.5), 0 0 0 2px rgba(34, 211, 238, 0.6)';
                                                        }}
                                                        onMouseLeave={(e) => {
                                                            e.currentTarget.style.transform = 'scale(1) rotate(0deg)';
                                                            e.currentTarget.style.background = 'linear-gradient(135deg, #10B981 0%, #059669 100%)';
                                                            e.currentTarget.style.boxShadow = '0 4px 12px rgba(16, 185, 129, 0.3), 0 0 0 1px rgba(34, 211, 238, 0.4)';
                                                        }}
                                                        onMouseDown={(e) => {
                                                            e.currentTarget.style.transform = 'scale(0.95)';
                                                        }}
                                                        onMouseUp={(e) => {
                                                            e.currentTarget.style.transform = 'scale(1.1) rotate(360deg)';
                                                        }}
                                                    >
                                                        <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                                                            <path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                                                            <path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                                                        </svg>
                                                    </button>
                                                </td>
                                            </tr>
                                            
                                            {/* Expanded Details Row */}
                                            {isExpanded && (
                                                <tr style={{
                                                    background: 'rgba(15, 23, 42, 0.6)',
                                                    borderBottom: index < filteredCandidates.length - 1 ? '1px solid rgba(34, 211, 238, 0.2)' : 'none',
                                                    borderTop: '1px solid rgba(34, 211, 238, 0.2)'
                                                }}>
                                                    <td colSpan={6} style={{ padding: '0' }}>
                                                        <div style={{
                                                            padding: '24px',
                                                            animation: 'slideDown 0.3s ease-out'
                                                        }}>
                                                            <div style={{
                                                                display: 'grid',
                                                                gridTemplateColumns: 'repeat(2, 1fr)',
                                                                gap: '20px',
                                                                marginBottom: '20px'
                                                            }}>
                                                                {/* Strengths */}
                                                                <div style={{
                                                                    background: 'rgba(34, 211, 238, 0.1)',
                                                                    border: '1px solid rgba(34, 211, 238, 0.3)',
                                                                    borderRadius: '8px',
                                                                    padding: '16px'
                                                                }}>
                                                                    <h4 style={{ color: '#22d3ee', fontSize: '14px', fontWeight: 600, marginBottom: '12px' }}>
                                                                        Strengths
                                                                    </h4>
                                                                    {evaluation?.strengths && evaluation.strengths.length > 0 ? (
                                                                        <ul style={{ margin: 0, paddingLeft: '20px', color: '#CBD5E1', fontSize: '13px', lineHeight: '1.8' }}>
                                                                            {evaluation.strengths.map((strength, i) => (
                                                                                <li key={i} style={{ marginBottom: '6px' }}>{strength}</li>
                                                                            ))}
                                                                        </ul>
                                                                    ) : (
                                                                        <span style={{ color: '#94A3B8', fontSize: '13px' }}>None</span>
                                                                    )}
                                                                </div>

                                                                {/* Weaknesses */}
                                                                <div style={{
                                                                    background: 'rgba(34, 211, 238, 0.1)',
                                                                    border: '1px solid rgba(34, 211, 238, 0.3)',
                                                                    borderRadius: '8px',
                                                                    padding: '16px'
                                                                }}>
                                                                    <h4 style={{ color: '#22d3ee', fontSize: '14px', fontWeight: 600, marginBottom: '12px' }}>
                                                                        Weaknesses
                                                                    </h4>
                                                                    {evaluation?.weaknesses && evaluation.weaknesses.length > 0 ? (
                                                                        <ul style={{ margin: 0, paddingLeft: '20px', color: '#CBD5E1', fontSize: '13px', lineHeight: '1.8' }}>
                                                                            {evaluation.weaknesses.map((weakness, i) => (
                                                                                <li key={i} style={{ marginBottom: '6px' }}>{weakness}</li>
                                                                            ))}
                                                                        </ul>
                                                                    ) : (
                                                                        <span style={{ color: '#94A3B8', fontSize: '13px' }}>None</span>
                                                                    )}
                                                                </div>

                                                                {/* Red Flags */}
                                                                <div style={{
                                                                    background: 'rgba(34, 211, 238, 0.1)',
                                                                    border: '1px solid rgba(34, 211, 238, 0.3)',
                                                                    borderRadius: '8px',
                                                                    padding: '16px'
                                                                }}>
                                                                    <h4 style={{ color: '#22d3ee', fontSize: '14px', fontWeight: 600, marginBottom: '12px' }}>
                                                                        Red Flags
                                                                    </h4>
                                                                    {evaluation?.red_flags && evaluation.red_flags.length > 0 ? (
                                                                        <ul style={{ margin: 0, paddingLeft: '20px', color: '#CBD5E1', fontSize: '13px', lineHeight: '1.8' }}>
                                                                            {evaluation.red_flags.map((flag, i) => (
                                                                                <li key={i} style={{ marginBottom: '6px' }}>{flag}</li>
                                                                            ))}
                                                                        </ul>
                                                                    ) : (
                                                                        <span style={{ color: '#94A3B8', fontSize: '13px' }}>None</span>
                                                                    )}
                                                                </div>

                                                                {/* Summary */}
                                                                <div style={{
                                                                    background: 'rgba(34, 211, 238, 0.1)',
                                                                    border: '1px solid rgba(34, 211, 238, 0.3)',
                                                                    borderRadius: '8px',
                                                                    padding: '16px'
                                                                }}>
                                                                    <h4 style={{ color: '#22d3ee', fontSize: '14px', fontWeight: 600, marginBottom: '12px' }}>
                                                                        Summary
                                                                    </h4>
                                                                    <p style={{ color: '#CBD5E1', fontSize: '13px', lineHeight: '1.8', margin: 0 }}>
                                                                        {evaluation?.summary || 'No summary available'}
                                                                    </p>
                                                                </div>
                                                            </div>
                                                        </div>
                                                    </td>
                                                </tr>
                                            )}
                                            </React.Fragment>
                                        );
                                    })}
                                </tbody>
                            </table>
                        </div>
                    </div>
                )}

                {/* Stats */}
                {!loading && candidates.length > 0 && (
                    <div style={{
                        marginTop: '30px',
                        display: 'grid',
                        gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
                        gap: '20px'
                    }}>
                        <div style={{
                            background: 'rgba(15, 23, 42, 0.5)',
                            padding: '20px',
                            borderRadius: '12px',
                            border: '1px solid rgba(148, 163, 184, 0.1)'
                        }}>
                            <div style={{ color: '#94A3B8', fontSize: '14px', marginBottom: '8px' }}>Total Evaluations</div>
                            <div style={{ color: '#F1F5F9', fontSize: '28px', fontWeight: 700 }}>{candidates.length}</div>
                        </div>
                        <div style={{
                            background: 'rgba(15, 23, 42, 0.5)',
                            padding: '20px',
                            borderRadius: '12px',
                            border: '1px solid rgba(148, 163, 184, 0.1)'
                        }}>
                            <div style={{ color: '#94A3B8', fontSize: '14px', marginBottom: '8px' }}>Hire</div>
                            <div style={{ color: '#10B981', fontSize: '28px', fontWeight: 700 }}>
                                {candidates.filter(c => c.writtenInterviewEvaluation?.recommendation === 'Hire').length}
                            </div>
                        </div>
                        <div style={{
                            background: 'rgba(15, 23, 42, 0.5)',
                            padding: '20px',
                            borderRadius: '12px',
                            border: '1px solid rgba(148, 163, 184, 0.1)'
                        }}>
                            <div style={{ color: '#94A3B8', fontSize: '14px', marginBottom: '8px' }}>Consider</div>
                            <div style={{ color: '#F59E0B', fontSize: '28px', fontWeight: 700 }}>
                                {candidates.filter(c => c.writtenInterviewEvaluation?.recommendation === 'Consider').length}
                            </div>
                        </div>
                        <div style={{
                            background: 'rgba(15, 23, 42, 0.5)',
                            padding: '20px',
                            borderRadius: '12px',
                            border: '1px solid rgba(148, 163, 184, 0.1)'
                        }}>
                            <div style={{ color: '#94A3B8', fontSize: '14px', marginBottom: '8px' }}>Reject</div>
                            <div style={{ color: '#EF4444', fontSize: '28px', fontWeight: 700 }}>
                                {candidates.filter(c => c.writtenInterviewEvaluation?.recommendation === 'Reject').length}
                            </div>
                        </div>
                    </div>
                )}
            </div>
        </div>
        </>
    );
};

export default WrittenInterview;

